package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import team.creative.littletiles.common.math.box.*;import team.creative.littletiles.common.math.box.collection.*;import team.creative.littletiles.common.placement.shape.LittleShape;import team.creative.littletiles.common.placement.shape.type.*;
public final class UniformOutlineDragResolution {
 public static LittleBoxes apply(LittleShape shape,LittleBoxes boxes){if(!(shape instanceof LittleShapeCurve||shape instanceof LittleShapeCurveWall||shape instanceof LittleShapeCatenary)||boxes.all().size()<2048)return boxes;int[] min={Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE},max={Integer.MIN_VALUE,Integer.MIN_VALUE,Integer.MIN_VALUE};for(var b:boxes.all()){if(b.getClass()!=LittleBox.class||b.maxX-b.minX<4||b.maxY-b.minY<4||b.maxZ-b.minZ<4)return boxes;min[0]=Math.min(min[0],b.minX);min[1]=Math.min(min[1],b.minY);min[2]=Math.min(min[2],b.minZ);max[0]=Math.max(max[0],b.maxX);max[1]=Math.max(max[1],b.maxY);max[2]=Math.max(max[2],b.maxZ);}var out=new LittleBoxesSimple(boxes.pos,boxes.grid);LittleBox previous=null;for(var b:boxes.all()){int x=shift(b.minX,b.maxX,min[0],max[0]),y=shift(b.minY,b.maxY,min[1],max[1]),z=shift(b.minZ,b.maxZ,min[2],max[2]);var next=new LittleBox(b.minX+x,b.minY+y,b.minZ+z,b.maxX+x,b.maxY+y,b.maxZ+z);if(previous==null||!next.equals(previous))out.add(next);previous=next;}return out;}
 private static int shift(int lo,int hi,int min,int max){if(lo==min||hi==max)return 0;long rounded=Math.floorDiv((long)lo+1,2)*2;return (int)(Math.max(min,Math.min((long)max-(hi-lo),rounded))-lo);}
}
